using namespace std;

int main() {
    long long n, i, k, s = 0;
    cin >> n;

    i = n - 1;
    k = 1;

    while (i > k) {
        s += i * k;
        --i;
        ++k;
    }

    s = 2 * s + (i == k ? i * i : 0) + n;
    cout << s;

    return 0;
}

